def ket(j, dim):
    """Input:
    j: int or list, the index/indices of the basis vector(s)
    dim: int or list, dimension(s) of the ket
    Output:
    out: numpy array of float, the matrix representation of the ket
    """
    if isinstance(j, int):
        if isinstance(dim, int):
            out = np.zeros(dim)
            out[j] = 1.0
            return out
        else:
            j = [j]
    if isinstance(dim, int):
        dims = [dim] * len(j)
    else:
        dims = dim
    result = None
    for idx, dim_i in zip(j, dims):
        basis_vec = np.zeros(dim_i)
        basis_vec[idx] = 1.0
        if result is None:
            result = basis_vec
        else:
            result = np.kron(result, basis_vec)
    return result

def tensor(*args):
    """Takes the tensor product of an arbitrary number of matrices/vectors.
    Input:
    args: any number of nd arrays of floats, corresponding to input matrices
    Output:
    M: the tensor product (kronecker product) of input matrices, 2d array of floats
    """
    if len(args) == 0:
        return np.array([[1.0]])
    result = args[0]
    for matrix in args[1:]:
        result = np.kron(result, matrix)
    return result
